  // src/docx.js
  var SIG_EOCD = 101010256;
  var SIG_CENTRAL = 33639248;
  var SIG_LOCAL = 67324752;
  var utf8 = new TextDecoder("utf-8");
  var canInflate = () => typeof DecompressionStream !== "undefined";
  function entries(buffer) {
    const v = new DataView(buffer);
    const bytes = new Uint8Array(buffer);
    let eocd = -1;
    for (let i = buffer.byteLength - 22; i >= Math.max(0, buffer.byteLength - 22 - 65535); i--) {
      if (v.getUint32(i, true) === SIG_EOCD) {
        eocd = i;
        break;
      }
    }
    if (eocd === -1) throw new Error("not a zip file");
    const count2 = v.getUint16(eocd + 10, true);
    let p = v.getUint32(eocd + 16, true);
    const out = [];
    for (let n = 0; n < count2; n++) {
      if (v.getUint32(p, true) !== SIG_CENTRAL) throw new Error("bad central directory");
      const method = v.getUint16(p + 10, true);
      const compressedSize = v.getUint32(p + 20, true);
      const size = v.getUint32(p + 24, true);
      const nameLen = v.getUint16(p + 28, true), extraLen = v.getUint16(p + 30, true), commentLen = v.getUint16(p + 32, true);
      const offset = v.getUint32(p + 42, true);
      const name = utf8.decode(bytes.subarray(p + 46, p + 46 + nameLen));
      out.push({ name, method, compressedSize, size, offset });
      p += 46 + nameLen + extraLen + commentLen;
    }
    return out;
  }
  function rawData(buffer, entry) {
    const v = new DataView(buffer);
    if (v.getUint32(entry.offset, true) !== SIG_LOCAL) throw new Error("bad local header");
    const nameLen = v.getUint16(entry.offset + 26, true), extraLen = v.getUint16(entry.offset + 28, true);
    const start2 = entry.offset + 30 + nameLen + extraLen;
    return new Uint8Array(buffer, start2, entry.compressedSize);
  }
  async function inflate(bytes) {
    const ds = new DecompressionStream("deflate-raw");
    const stream = new Blob([bytes]).stream().pipeThrough(ds);
    return new Uint8Array(await new Response(stream).arrayBuffer());
  }
  async function readEntry(buffer, name) {
    const entry = entries(buffer).find((e) => e.name === name);
    if (!entry) return null;
    const raw = rawData(buffer, entry);
    if (entry.method === 0) return utf8.decode(raw);
    if (entry.method === 8) {
      if (!canInflate()) throw new Error("This browser cannot read Word files; paste the text instead.");
      return utf8.decode(await inflate(raw));
    }
    throw new Error(`unsupported compression ${entry.method}`);
  }
  var readDocumentXml = (buffer) => readEntry(buffer, "word/document.xml");

  // src/ui/sourcesheet.js
  function openPasteSheet({ onUse }) {
    const ov = document.createElement("div");
    ov.className = "overlay";
    ov.innerHTML = `
  <div class="sheet" role="dialog" aria-label="Paste transcript">
    <div class="sheet-handle"></div>
    <div class="sheet-head">
      <span class="section-title">Paste transcript</span>
      <button class="icon-btn" data-close aria-label="Close">${icon("x")}</button>
    </div>
    <textarea class="input paste-area" data-text placeholder="Paste the transcript here" aria-label="Transcript text" autocapitalize="off" spellcheck="false"></textarea>
    <span class="hint">Lines like “Marco: …” or “[00:12] Marco: …” become speakers.</span>
    <button class="btn btn-primary btn-block" data-use disabled>Use</button>
  </div>`;
    document.body.appendChild(ov);
    const unpin = pinToViewport(ov);
    const q = (s) => ov.querySelector(s);
    const close = () => {
      unpin();
      ov.remove();
      document.removeEventListener("keydown", onKey);
    };
    const onKey = (e) => {
      if (e.key === "Escape") close();
    };
    document.addEventListener("keydown", onKey);
    ov.addEventListener("click", (e) => {
      if (e.target === ov) close();
    });
    q("[data-close]").addEventListener("click", close);
    const area = q("[data-text]"), use = q("[data-use]");
    area.addEventListener("input", () => {
      use.disabled = !area.value.trim();
    });
    use.addEventListener("click", () => {
      const parsed = parsePasted(area.value);
      if (!parsed.segments.length) return;
      close();
      onUse(parsed);
    });
    area.focus();
  }
  var ACCEPT = ".txt,.vtt,.srt,.docx,text/plain,text/vtt,application/x-subrip";
  var MAX_BYTES = 5 * 1024 * 1024;
  function pickTranscriptFile({ onParsed, onError }) {
    const input = document.createElement("input");
    input.type = "file";
    input.accept = ACCEPT;
    input.style.display = "none";
    document.body.appendChild(input);
    input.addEventListener("change", () => {
      const file = input.files?.[0];
      input.remove();
      if (!file) return;
      const ext = file.name.toLowerCase().split(".").pop();
      if (!["txt", "vtt", "srt", "docx"].includes(ext)) {
        onError("Choose a .txt, .vtt, .srt or .docx file.");
        return;
      }
      if (file.size > MAX_BYTES) {
        onError("That file is too large to be a transcript.");
        return;
      }
      const finish3 = (text2) => {
        const parsed = parseByName(ext === "docx" ? "x.txt" : file.name, text2);
        if (!parsed.segments.length) {
          onError("Couldn't read this file: it has no text.");
          return;
        }
        onParsed(file.name, parsed);
      };
      if (ext === "docx") {
        if (!canInflate()) {
          onError("This browser cannot read Word files; paste the text instead.");
          return;
        }
        file.arrayBuffer().then((buf) => readDocumentXml(buf)).then((xml) => {
          if (xml === null) throw new Error("not a Word file");
          finish3(parseDocxXml(xml));
        }).catch(() => onError("Couldn't read this file: it is not a Word document."));
        return;
      }
      const reader = new FileReader();
      reader.onerror = () => onError("Couldn't read this file.");
      reader.onload = () => finish3(String(reader.result || ""));
      reader.readAsText(file);
    });
    input.click();
  }

